/**
 * Preset Utilities
 *
 * Helpers for extending and composing physics model presets.
 *
 * ```js
 * import { extendPreset, ArcadeModel } from '@three-blocks/pro';
 *
 * const fastArcade = extendPreset( ArcadeModel, {
 *   name: 'fast-arcade',
 *   config: { ...ArcadeModel.config, maxSpeed: 14 },
 * } );
 * ```
 *
 * @module @three-blocks/pro/physics/models/extendPreset
 * @short Helpers for extending and composing physics presets.
 * @category Physics
 * @tags Presets, Utilities, Physics
 */
/**
 * Extends a base physics preset with custom overrides.
 * Allows users to modify specific behaviors while inheriting the rest.
 *
 * @param {PhysicsModel} basePreset - The preset to extend.
 * @param {Object} overrides - Partial PhysicsModel properties to override.
 * @returns {PhysicsModel} The extended preset.
 *
 * @example
 * import { extendPreset, ArcadeModel } from '@three-blocks/pro';
 *
 * const custom = extendPreset( ArcadeModel, {
 *   name: 'custom-arcade',
 *   config: { ...ArcadeModel.config, jumpVelocity: 12 },
 * } );
 */
export function extendPreset(basePreset: PhysicsModel, overrides: any): PhysicsModel;
/**
 * Creates a preset with scaled physics values.
 *
 * Note: This utility targets legacy presets that expose
 * `getForceMultiplier`, `getGravityBonus`, `getFriction`, and `getJumpVelocity`.
 *
 * @param {PhysicsModel} basePreset - The preset to scale.
 * @param {Object} scales - Scale factors for each property.
 * @param {number} [scales.force=1] - Force multiplier scale.
 * @param {number} [scales.gravity=1] - Gravity bonus scale.
 * @param {number} [scales.friction=1] - Friction scale.
 * @param {number} [scales.jump=1] - Jump velocity scale.
 * @param {string} [name] - Optional name for the scaled preset.
 * @returns {PhysicsModel}
 *
 * @example
 * const heavy = scalePreset( legacyModel, { gravity: 1.5, jump: 0.8 }, 'heavy' );
 */
export function scalePreset(basePreset: PhysicsModel, scales: {
    force?: number;
    gravity?: number;
    friction?: number;
    jump?: number;
}, name?: string): PhysicsModel;
/**
 * Combines multiple presets by using the first matching non-null result.
 *
 * Note: This utility targets legacy presets that expose
 * `getForceMultiplier`, `getGravityBonus`, `getFriction`, and `getJumpVelocity`.
 *
 * @param {string} name - Name for the combined preset.
 * @param {Array<{condition: function(BodyState): boolean, preset: PhysicsModel}>} presetConfigs
 * @param {PhysicsModel} fallback - Fallback preset if no conditions match.
 * @returns {PhysicsModel}
 *
 * @example
 * const conditionalPreset = combinePresets( 'conditional', [
 *   { condition: ( state ) => state.sliding, preset: slipperyLegacyModel },
 * ], fallbackLegacyModel );
 */
export function combinePresets(name: string, presetConfigs: Array<{
    condition: (arg0: BodyState) => boolean;
    preset: PhysicsModel;
}>, fallback: PhysicsModel): PhysicsModel;
